CustomField.formula:
IF(
   Indicador_Fecha_de_Acuse__c = "/img/samples/flag_green.gif",
   0,
   (
       /* Calcula los días totales entre las dos fechas */
       TODAY() - DATEVALUE(Fecha_de_Acuse__c)
   ) - 
   (
       /* Calcula los fines de semana entre las dos fechas */
       FLOOR((TODAY() - DATEVALUE(Fecha_de_Acuse__c))/7)*2 +
       IF(MOD(TODAY() - DATEVALUE(Fecha_de_Acuse__c), 7) = 6, 1, 0) +
       IF(MOD(TODAY() - DATEVALUE(Fecha_de_Acuse__c), 7) = 0, 1, 0)
   )
)
